# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HADİSLERİN RESMÎ TEDVİN DÖNEMİ (HİCRİ I. ASIR SONU - II. ASIR BAŞI)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">TEDVİN KAVRAMI VE ÖNCÜ İSİMLER</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Tedvin: Dağınık sahîfe ve hafızalardaki hadislerin</text>\n  <text x="35" y="106" font-size="11.2" fill="#1e3a8a">  devlet eliyle resmî olarak bir araya toplanmasıdır.</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">• Resmî Emri Veren: Halife Ömer bin Abdülaziz (99-101 H.)</text>\n  <text x="35" y="150" font-size="11.2" fill="#1e3a8a">• Medine Valisi: Ebû Bekir bin Muhammed bin Hazm</text>\n  <text x="35" y="172" font-size="11.2" fill="#1e3a8a">• İlk Müdevvin (Toplayan): İbn Şihâb ez-Zührî (v. 124/742)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TEDVİNİ ZORUNLU KILAN SEBEPLER</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• 1. Sahabe ve büyük tâbiîn hafızlarının vefat etmesi</text>\n  <text x="370" y="110" font-size="11.2" fill="#14532d">• 2. İslam coğrafyasının genişlemesi ve ravilerin dağılması</text>\n  <text x="370" y="132" font-size="11.2" fill="#14532d">• 3. Siyasi/itikadi fırkaların ortaya çıkışı ve hadis</text>\n  <text x="370" y="150" font-size="11.2" fill="#14532d">  uydurma (vaz\') tehlikesine karşı sahih sünneti koruma</text>\n  <text x="370" y="172" font-size="11.2" font-weight="bold" fill="#166534">• Özellik: Konu ayrımı yapılmadan bütün hadisler toplandı.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«İlmin kaybolmasından ve alimlerin vefatından korkuyorum...» (Ömer bin Abdülaziz\'in Tedvin Fermanı)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TASNİF DÖNEMİ VE SİSTEMLERİNE GÖRE İLK HADİS MECMUALARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">1. KONULARINA GÖRE TASNİF (ALE\'L-EBVÂB)</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• Musannef: Merfû, mevkuf ve maktû haberleri fıkıh</text>\n  <text x="35" y="106" font-size="11.2" fill="#713f12">  bablarına göre dizer (Abdürrezzâk, İbn Ebî Şeybe).</text>\n  <text x="35" y="128" font-size="11.2" fill="#713f12">• Muvatta: İmam Mâlik bin Enes\'in Hicaz uygulaması ve</text>\n  <text x="35" y="146" font-size="11.2" fill="#713f12">  hadisleri fıkıh konularına göre topladığı ilk meşhur eser.</text>\n  <text x="35" y="168" font-size="11.2" fill="#713f12">• Câmi\' (tüm konular) ve Sünen (ahkâm/fıkıh konuları)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">2. RAVİLERİNE GÖRE TASNİF (ALE\'R-RİCÂL)</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Müsned: Hadislerin konularına göre değil, hadisi ilk</text>\n  <text x="370" y="106" font-size="11.2" fill="#581c87">  rivayet eden sahabi isimlerine göre sıralandığı eserdir.</text>\n  <text x="370" y="128" font-size="11.2" fill="#581c87">• En Meşhur Örnek: Ahmed bin Hanbel\'in el-Müsned\'i</text>\n  <text x="370" y="146" font-size="11.2" fill="#581c87">  (Yaklaşık 30.000 hadis; Aşere-i Mübeşşere ile başlar).</text>\n  <text x="370" y="168" font-size="11.2" fill="#581c87">• Mu\'cem: Sahabi veya hoca adlarını alfabetik sıralar (Taberânî).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Tedvin hadisleri bir araya toplama, Tasnif ise toplanan hadisleri belirli bir sisteme göre sınıflandırmadır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ALTIN ÇAĞ (HİCRİ III. ASIR): KÜTÜB-İ SİTTE VE KÜTÜB-İ TİS\'A</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">SAHÎHAYN VE CÂMİ\' TÜRÜ ESERLER</text>\n  <text x="35" y="88" font-size="11.2" fill="#7c2d12">• 1. Buhârî (v. 256): el-Câmiu\'s-Sahîh (İlk müstakil sahih)</text>\n  <text x="35" y="110" font-size="11.2" fill="#7c2d12">• 2. Müslim (v. 261): el-Câmiu\'s-Sahîh (Buhârî ile Sahîhayn)</text>\n  <text x="35" y="132" font-size="11.2" fill="#7c2d12">• 3. Tirmizî (v. 279): es-Sünen / el-Câmi\' (Hasen terimini</text>\n  <text x="35" y="150" font-size="11.2" fill="#7c2d12">  yaygınlaştırdı, hadislerin sıhhat derecelerini belirtti).</text>\n  <text x="35" y="172" font-size="11.2" font-weight="bold" fill="#9a3412">• Câmi\': İman, ahkâm, tefsir, siyer, fiten (8 ana bölüm)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">ERBAA-İ SÜNEN VE KÜTÜB-İ TİS\'A EKLERİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#164e63">• 4. Ebû Dâvûd (v. 275): es-Sünen (Ahkâm hadisleri odaklı)</text>\n  <text x="370" y="110" font-size="11.2" fill="#164e63">• 5. Nesâî (v. 303): es-Sünen (el-Müctebâ)</text>\n  <text x="370" y="132" font-size="11.2" fill="#164e63">• 6. İbn Mâce (v. 273): es-Sünen (Kütüb-i Sitte\'nin 6. halkası)</text>\n  <text x="370" y="154" font-size="11.2" fill="#164e63">• Kütüb-i Tis\'a (9 Eser): Kütüb-i Sitte + İmam Mâlik</text>\n  <text x="370" y="172" font-size="11.2" fill="#164e63">  (Muvatta) + Ahmed bin Hanbel (Müsned) + Dârimî (Sünen)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hicri III. asır hadis ilminin \'Altın Çağı\'dır; sahih hadisler zayıf rivayetlerden titizlikle ayrılmıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
